-- VBC Analytics Semantic View — with lab additions
-- Adds PATIENT_INCOME_BAND + ENCOUNTER_MONTH/YEAR dimensions and 5 VBC metrics
-- to the Autopilot-generated baseline. Run this script in your snowday workspace.
-- CREATE OR ALTER is idempotent: updates in place if the view already exists.

create or alter semantic view VBC_LAB.CARE_ANALYTICS.VBC_ANALYTICS_SV
	tables (
		SYNTHEA.SILVER.CONDITIONS comment='The table contains records of medical conditions diagnosed for patients. Each record represents a single condition instance, capturing the condition''s coded classification, associated patient and encounter, the duration of the condition, and the city of the synthetic patient.',
		SYNTHEA.SILVER.ENCOUNTERS primary key (ENCOUNTER_ID) comment='The table contains records of patient medical encounters, capturing details about individual healthcare visits or interactions. Each record includes information about the involved parties (patient, provider, organization, and payer), the nature and classification of the encounter, associated costs and insurance coverage, and the reason for the visit.',
		SYNTHEA.SILVER.MEDICATIONS comment='The table contains records of medication prescriptions associated with patient encounters. Each record represents a single medication course and includes details about the medication itself, associated costs and payer coverage, the reason for prescribing, and the geographic location of the patient.',
		SYNTHEA.SILVER.OBSERVATIONS comment='The table contains records of clinical observations captured during patient encounters. Each record represents a single observation and includes details about the patient, the associated encounter, and the nature of the observation such as its category, coded description, measured value, and units of measurement.',
		SYNTHEA.SILVER.PATIENTS primary key (PATIENT_ID) comment='The table contains records of individual patients, including personal identifying information and demographic details. Each record represents a single patient and covers attributes such as biographical dates, identity documents, name components, and demographic characteristics including marital status, race, ethnicity, gender, and geographic information.',
		SYNTHEA.SILVER.PAYERS primary key (PAYER_ID) comment='The table contains records of health insurance payers, including their contact and location details. Each record represents a single payer and includes financial summaries such as revenue, covered and uncovered amounts, and utilization metrics across encounters, medications, procedures, and immunizations, as well as customer counts and average quality of life scores.',
		SYNTHEA.SILVER.PROCEDURES comment='The table contains records of medical procedures performed on patients. Each record represents a single procedure and includes details about the associated patient and encounter, the procedure type and description, cost information, and the reason for the procedure, scoped to a specific city.',
		SYNTHEA.SILVER.PROVIDERS primary key (PROVIDER_ID) comment='The table contains records of healthcare providers and their associated attributes. Each record represents an individual provider and includes details about their identity, demographics, medical speciality, geographic location, and affiliated organization, along with aggregate counts of encounters and procedures.'
	)
	relationships (
		CONDITIONS_TO_ENCOUNTERS as CONDITIONS(ENCOUNTER_ID) references ENCOUNTERS(ENCOUNTER_ID),
		CONDITIONS_TO_PATIENTS as CONDITIONS(PATIENT_ID) references PATIENTS(PATIENT_ID),
		ENCOUNTERS_TO_PATIENTS as ENCOUNTERS(PATIENT_ID) references PATIENTS(PATIENT_ID),
		ENCOUNTERS_TO_PAYERS as ENCOUNTERS(PAYER_ID) references PAYERS(PAYER_ID),
		ENCOUNTERS_TO_PROVIDERS as ENCOUNTERS(PROVIDER_ID) references PROVIDERS(PROVIDER_ID),
		MEDICATIONS_TO_ENCOUNTERS as MEDICATIONS(ENCOUNTER_ID) references ENCOUNTERS(ENCOUNTER_ID),
		MEDICATIONS_TO_PATIENTS as MEDICATIONS(PATIENT_ID) references PATIENTS(PATIENT_ID),
		MEDICATIONS_TO_PAYERS as MEDICATIONS(PAYER_ID) references PAYERS(PAYER_ID),
		OBSERVATIONS_TO_ENCOUNTERS as OBSERVATIONS(ENCOUNTER_ID) references ENCOUNTERS(ENCOUNTER_ID),
		OBSERVATIONS_TO_PATIENTS as OBSERVATIONS(PATIENT_ID) references PATIENTS(PATIENT_ID),
		PROCEDURES_TO_ENCOUNTERS as PROCEDURES(ENCOUNTER_ID) references ENCOUNTERS(ENCOUNTER_ID),
		PROCEDURES_TO_PATIENTS as PROCEDURES(PATIENT_ID) references PATIENTS(PATIENT_ID)
	)
	facts (
		ENCOUNTERS.BASE_ENCOUNTER_COST as BASE_ENCOUNTER_COST comment='The base cost of the encounter, not including any line item costs related to medications, immunizations, procedures, or other services.' sample_values ('183.23', '69.38', '112.97'),
		ENCOUNTERS.PAYER_COVERAGE as PAYER_COVERAGE comment='The amount of cost covered by the Payer.' sample_values ('731.68', '3436.72', '759.42'),
		ENCOUNTERS.TOTAL_CLAIM_COST as TOTAL_CLAIM_COST comment='The total cost of the encounter, including all line items.' sample_values ('41309.94', '2738.36', '904.92'),
		MEDICATIONS.BASE_COST as BASE_COST comment='The line item cost of the medication.' sample_values ('1.47', '0.73', '0.99'),
		MEDICATIONS.PAYER_COVERAGE as PAYER_COVERAGE comment='The amount covered or reimbursed by the Payer.' sample_values ('408.20', '64.62', '183.46'),
		MEDICATIONS.TOTALCOST as TOTALCOST comment='The total cost of the prescription, including all dispenses.' sample_values ('1.11', '8386.56', '7.68'),
		PATIENTS.HEALTHCARE_COVERAGE as HEALTHCARE_COVERAGE comment='The total lifetime cost of healthcare services that were covered by Payers (i.e. what the insurance company paid).' sample_values ('803376.48', '599541.28', '673725.25'),
		PATIENTS.HEALTHCARE_EXPENSES as HEALTHCARE_EXPENSES comment='The total lifetime cost of healthcare to the patient (i.e. what the patient paid).' sample_values ('38010.04', '14409.81', '1422104.61'),
		PATIENTS.LAT as LAT comment='Latitude of Patient address.' sample_values ('40.436537891992480', '40.464558951571960', '40.470892304824260'),
		PATIENTS.LON as LON comment='Longitude of Patient address.' sample_values ('-87.58418148560617', '-87.59906561377016', '-87.75167330498918'),
		PAYERS.AMOUNT_COVERED as AMOUNT_COVERED comment='The monetary amount paid to Organizations during the entire simulation.' sample_values ('396788738.40', '23970274422.24', '2050104327.31'),
		PAYERS.AMOUNT_UNCOVERED as AMOUNT_UNCOVERED comment='The monetary amount not paid to Organizations during the entire simulation, and covered out of pocket by patients.' sample_values ('2840318033.55', '72640882.24', '1743702849.19'),
		PAYERS.QOLS_AVG as QOLS_AVG comment='The average Quality of Life Scores (QOLS) for all patients enrolled with this Payer during the entire simulation.' sample_values ('0.90799848608661420', '0.85600658044812520', '0.93837731612506100'),
		PAYERS.REVENUE as REVENUE comment='The monetary revenue of the Payer during the entire simulation.' sample_values ('2718479175.30', '144143118.53', '93451732.97'),
		PROCEDURES.BASE_COST as BASE_COST comment='The line item cost of the procedure.' sample_values ('398.63', '6857.81', '434.05'),
		PROVIDERS.LAT as LAT comment='Latitude of Provider address.' sample_values ('41.520484800000000', '42.329843000000000', '42.281043200000000'),
		PROVIDERS.LON as LON comment='Longitude of Provider address.' sample_values ('-81.49950460000000', '-81.58649390000000', '-81.57577590000000')
	)
	dimensions (
		CONDITIONS._SYSTEM as "SYSTEM" comment='Coding system for the code' sample_values ('http://snomed.info/sct', 'SNOMED-CT'),
		CONDITIONS.CODE as CODE comment='Diagnosis code from SNOMED-CT' sample_values ('278588009', '266934004', '161744009'),
