		CONDITIONS.PATIENT_ID as PATIENT_ID comment='Foreign key to primary key in Patietns table.' sample_values ('1562014', '1561862', '1687728'),
		CONDITIONS.SYNTHEA_CITY as SYNTHEA_CITY comment='City generated by Synthea.' sample_values ('PITTSBURGH', 'AUSTIN', 'BOSTON'),
		CONDITIONS.CONDITION_START as CONDITION_START comment='The date the condition was diagnosed.' sample_values ('2013-08-25', '1946-02-17', '2024-10-09'),
		CONDITIONS.CONDITION_STOP as CONDITION_STOP comment='The date the condition resolved, if applicable.' sample_values ('2005-12-06', '2022-02-06', '1990-11-26'),
		ENCOUNTERS.CODE as CODE comment='Encounter code from SNOMED-CT.' sample_values ('394701000', '439708006', '50849002'),
		ENCOUNTERS.DESCRIPTION as DESCRIPTION comment='Description of the type of encounter.' sample_values ('Hospital admission (procedure)', 'Administration of vaccine to produce active immunity (procedure)', 'Outpatient procedure'),
		ENCOUNTERS.ENCOUNTER_ID as ENCOUNTER_ID comment='Primary key for table Encounters.' sample_values ('64338156', '57222869', '30346807'),
		ENCOUNTERS.ENCOUNTERCLASS as ENCOUNTERCLASS comment='The class of the encounter, such as ambulatory, emergency, inpatient, wellness, or urgentcare.' sample_values ('urgentcare', 'ambulatory', 'virtual'),
		-- ADDED: expression dimensions for time-based analysis
		ENCOUNTERS.ENCOUNTER_MONTH as DATE_TRUNC('MONTH', ENCOUNTER_START) comment='Month of encounter',
		ENCOUNTERS.ENCOUNTER_YEAR as YEAR(ENCOUNTER_START) comment='Year of encounter',
		ENCOUNTERS.ORGANIZATION_ID as ORGANIZATION_ID comment='Foreign key to primary key in Organizations table.' sample_values ('1001307', '1002705', '1002715'),
		ENCOUNTERS.PATIENT_ID as PATIENT_ID comment='Foreign key to primary key in Patietns table.' sample_values ('1257836', '2352804', '1332205'),
