	-- ADDED: VBC metrics
	metrics (
		ENCOUNTERS.TOTAL_COST_OF_CARE as SUM(TOTAL_CLAIM_COST) comment='Total cost of care across all encounters',
		ENCOUNTERS.PAYER_COVERAGE_RATE as DIV0(SUM(PAYER_COVERAGE), SUM(TOTAL_CLAIM_COST)) comment='Payer coverage rate',
		ENCOUNTERS.AVG_COST_PER_ENCOUNTER as AVG(TOTAL_CLAIM_COST) comment='Average cost per encounter',
		ENCOUNTERS.TOTAL_ENCOUNTER_COUNT as COUNT(ENCOUNTER_ID) comment='Total count of encounters',
